package com.aistock.prediction.portfolioanalysis;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.math.BigDecimal;import java.util.*;
import static com.aistock.prediction.portfolioanalysis.PortfolioRecords.*;import static com.aistock.prediction.portfolioanalysis.PortfolioTestEvidence.*;
class PortfolioCalculatorTest {
 final PortfolioCalculator calculator=new PortfolioCalculator();
 Calculation calc(PositionSnapshot s,QuoteBatch q){return calculator.calculate(s,q,new BigDecimal("50"));}
 @Test void manualExampleTotalsAndExactThresholdAreReproducible(){var r=calc(normal(),prices());assertEquals("5000.00",r.totals().marketValue());assertEquals("4000.00",r.totals().costAmount());assertEquals("1000.00",r.totals().floatingProfit());assertEquals("25.00",r.totals().returnPercent());assertEquals("COMPLETE",r.state());assertFalse(r.lines().get(0).concentrationTriggered());assertEquals("50.00",r.lines().get(0).weightPercent());assertEquals(r,calc(normal(),prices()));assertEquals(64,r.sourceHash().length());var high=calc(normal(),batch(quote("SH600030","30",DATE),quote("SH600276","12.5",DATE)));assertEquals("5500.00",high.totals().marketValue());assertTrue(high.lines().get(0).concentrationTriggered());}
 @Test void roundedDisplayAmountsAreSummedAndZeroRoundedCostHasNoReturn(){var r=calc(snapshot(position("SH600030","1","0.004"),position("SH600276","1","0")),batch(quote("SH600030","0.005",DATE),quote("SH600276","0.005",DATE)));assertEquals("0.02",r.totals().marketValue());assertEquals("0.00",r.totals().costAmount());assertEquals("0.02",r.totals().floatingProfit());assertNull(r.totals().returnPercent());assertNull(r.lines().get(0).returnPercent());assertFalse(r.lines().get(0).concentrationTriggered());var zero=calc(snapshot(position("SH600030","1","0")),batch(quote("SH600030","0.000001",DATE)));assertEquals("0.00",zero.totals().marketValue());assertNull(zero.lines().get(0).weightPercent());assertNull(zero.lines().get(0).concentrationTriggered());}
 @Test void missingAndMixedDatesNeverProduceFullPortfolioWeights(){var partial=calc(normal(),batch(quote("SH600030","25",DATE),missing("SH600276")));assertEquals("PARTIAL",partial.state());assertNull(partial.totals());assertEquals("2500.00",partial.subtotal().marketValue());assertNull(partial.lines().get(0).weightPercent());var mixed=calc(normal(),batch(quote("SH600030","25",DATE),quote("SH600276","12.5",DATE.minusDays(1))));assertEquals("MIXED_DATES",mixed.state());assertTrue(mixed.mixedDates());assertNull(mixed.totals());var both=calc(snapshot(position("SH600030","1","1"),position("SH600276","1","1"),position("SZ000001","1","1")),batch(quote("SH600030","2",DATE),quote("SH600276","2",DATE.minusDays(1)),missing("SZ000001")));assertEquals("PARTIAL",both.state());assertTrue(both.mixedDates());}
 @Test void allMissingIsUnknownRatherThanZeroAndEmptyHasExplicitZeroSubtotal(){var missing=calc(normal(),batch(missing("SH600030"),missing("SH600276")));assertNull(missing.subtotal().marketValue());assertNull(missing.subtotal().costAmount());assertNull(missing.totals());var empty=calc(snapshot(),batch());assertEquals("EMPTY",empty.state());assertEquals(0,empty.positionCount());assertEquals(0,empty.valuedCount());assertEquals("0.00",empty.subtotal().marketValue());assertNull(empty.totals());assertEquals("UNKNOWN",empty.freshness());}
 @Test void oneHundredPositionsAreCompleteAndCanonicalHashIgnoresOrdering(){var ps=new ArrayList<PositionItem>();var qs=new ArrayList<Quote>();for(int i=0;i<100;i++){var id="SH"+String.format("%06d",i);ps.add(position(id,"1","1"));qs.add(quote(id,"2",DATE));}var a=calc(snapshot(ps.toArray(PositionItem[]::new)),batch(qs.toArray(Quote[]::new)));Collections.reverse(ps);Collections.reverse(qs);var b=calc(snapshot(ps.toArray(PositionItem[]::new)),batch(qs.toArray(Quote[]::new)));assertEquals(100,a.valuedCount());assertEquals("200.00",a.totals().marketValue());assertEquals(a.sourceHash(),b.sourceHash());}
 @Test void concentrationUsesExactRatioEvenWhenDisplayRoundsToFifty(){var r=calc(snapshot(position("SH600030","1","1"),position("SH600276","1","1")),batch(quote("SH600030","5000.4",DATE),quote("SH600276","4999.6",DATE)));assertEquals("50.00",r.lines().get(0).weightPercent());assertTrue(r.lines().get(0).concentrationTriggered());assertFalse(r.lines().get(1).concentrationTriggered());}
}
